from __future__ import annotations
import itertools, math
from typing import Sequence, Tuple

P1 = Tuple[float]


def d1(a: P1, b: P1) -> float:
    return abs(a[0]-b[0])


def score(corpus: Sequence[P1], x: P1) -> float:
    return min(d1(x,s) for s in corpus)


def comp_novelty(S, T, p) -> float:
    return min(score(S, p[0]), score(T, p[1]))


def prod_linf(p, q) -> float:
    return max(d1(p[0],q[0]), d1(p[1],q[1]))


def main() -> None:
    S = [(0.0,), (5.0,)]; T = [(0.0,), (4.0,)]
    pts = [((1.0,),(1.0,)), ((2.5,),(3.0,)), ((4.0,),(0.5,))]
    for p in pts:
        print(f'  comp{p} = {comp_novelty(S,T,p):.3f} (weakest link)')
    worst = max(abs(comp_novelty(S,T,p)-comp_novelty(S,T,q))/prod_linf(p,q)
                for p,q in itertools.combinations(pts,2))
    print(f'worst Lipschitz ratio = {worst:.3f} (theory: <= 1)')


if __name__ == '__main__':
    main()

