function NoveltyCertificate(S, x, eps, dist):
    if S is empty:
        return (score = +inf, certified = True)   # nothing known
    best <- +inf
    for s in S:
        d <- dist(x, s)
        if d < best:
            best <- d
    score <- best
    certified <- (score >= eps)                    # duality theorem
    return (score, certified)

