function AdaptiveThreshold(S, dist):
    if |S| < 2:
        return +inf                       # no resolution to speak of
    sigma <- +inf
    for each unordered pair {a, b} in S with a != b:
        d <- dist(a, b)
        if d < sigma:
            sigma <- d
    return sigma                          # exactly discriminating threshold

function CertifyAdaptive(S, x, dist):
    sigma <- AdaptiveThreshold(S, dist)
    score <- min_{s in S} dist(x, s)
    return (score >= sigma)

