function FiltrationSweep(S, x, [delta_1 < ... < delta_k], dist):
    score <- min_{s in S} dist(x, s)
    verdicts <- empty list
    for i in 1..k:
        verdicts[i] <- (delta_i <= score)     # antitone chain
    birth <- 0
    death <- score                            # x novel iff delta in [0, score)
    return (persistence = [birth, death), verdicts)
